data.query:
query Query($inventoryNumber: String!, $shipperFulfillmentId: String!) {
  inventory(where: {number:{_eq:$inventoryNumber} active:{_eq:true}}) {
    edges {
      node {
        id
				active
        barcode
        number
        trackingNumber
        location {
          id
          name
          locationType {
            id
            name
            inventory
            qualityHold
          }
        }
        inventoryStatus {
          id
          name
          active
          suspect
          moveLock
          shippable
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight
        inventoryStatus {
          id
          name
          active
          moveLock
          mergeLock
          splitLock

        }
        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            moveLock
            mergeLock
          }
        }
        supplier {
          id
          name
          externalId
          status
        }
        productStrategyProcess {
          id
          code          
          unitWeight
          productStrategy {
            id
            code
            name
            product {
              id
              code
              name
            }
          }
        }
        inventoryShipperLineFulfillmentSteps {
          edges {
            node {
              id
              inventoryId
              masterInventoryId
              isPicked
              isCompleted
            }
          }
        }
      }
    }
  }
  productionSetupMaterial(where:{inventory:{number:{_eq:$inventoryNumber}}}) {
    edges {
      node {
        id
        number
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  }
  transactionType(where:{shipmentLoad:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
  shipperFulfillment(where:{id:{_eq:$shipperFulfillmentId}}) {
    edges {
      node {
        id
        number
        shipperLineFulfillments {
          edges {
            node {
              id
              lineQuantity
              shipmentLine {
                productId
              }
              shipperLineFulfillmentSteps {
                edges {
                  node {
                    id
                    number
                    isPicked
                    isCompleted
                    quantity
                  }
                }
              } 
            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $productId := $.inventory.edges.node.productStrategyProcess.productStrategy.product.id;
  $quantity := $.inventory.edges.node.quantity.value;

  $foundProduct := $.shipperFulfillment.edges.node
    /*filter out matching products*/
    .shipperLineFulfillments.edges.node[shipmentLine.productId=$productId];

  $foundFulfillment := $.shipperFulfillment.edges.node
    /*filter out matching products*/
    .shipperLineFulfillments.edges.node[shipmentLine.productId=$productId]
      /*filter out products with enough quantity*/
      .shipperLineFulfillmentSteps.edges.node[isPicked=false and quantity>=$quantity]
        /*sort by the smallest amount*/
        ^(quantity)
          /*pluck the first row*/
          [0];
  {
    "foundFulfillment": $foundFulfillment,
    "foundProduct": $foundProduct
  }
)

data.responseTransform:
{
  "message": "A fulfillment request for Inventory (" & $state.context.REQUEST.inventoryNumber & ") was not big enough to allow this pick.",
  "success": false,
  "options": {
    "severity": "error"
  },
  "data": $state.context
}

{
  "message": "Inventory must exist in Fuuz and be active.",
  "success": false,
  "options": {
    "severity": "error"
  },
  "data": $state.context
}

{
  "message": "Inventory (" & $.inventory.edges.node.number & ") is loaded to workcenter (" & $.productionSetupMaterial.edges.node.productionSetup.workcenter.name & ") and cannot be split.  Please unload it first.",
  "success": false,
  "options": {
    "severity": "error"
  },
  "data": $state.context
}

{
  "message": "Inventory (" & $.inventory.edges.node.number & ") is in a restricted status (" & $.inventory.edges.node.inventoryStatus.name & ") and cannot be split.",
  "success": false,
  "options": {
    "severity": "error"
  },
  "data": $state.context
}

{
  "message": "A fulfillment request for Inventory (" & $state.context.REQUEST.inventoryNumber & ") was not found for this product.",
  "success": false,
  "options": {
    "severity": "error"
  },
  "data": $state.context
}

